with fx['ns']['sync_playwright']() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':1280,'height':1000});ctx.route('https://www.gstatic.com/firebasejs/**',mcq_sdk);page=ctx.new_page();page.route('**/api/staff-access',lambda route:mcq_api(page,route));page.goto('http://127.0.0.1:8000/cbse-mission.html#tab=mcq&mcqClass=X&mcq=bank');page.get_by_text('0 questions · page 1',exact=True).wait_for()
 root['mcq']=page.evaluate("""async draft=>{const {contributeMCQ}=await import('./cbse-mcq-model.js');let bank={};for(const [i,name]of ['Teacher Alpha','Teacher Beta','Teacher Alpha'].entries())bank=contributeMCQ(bank,{classId:'X',subjectId:'english',single:true,verified:true,topic:i===2?'Poetry':'Grammar',requestId:'bank_contributor_'+i,questions:[{verbatim:true,stem:'Question '+i+' A) One B) Two C) Three D) Four',answer:'A'}]},{id:'X:'+(i===2?0:i),name},draft,1).next;return bank;}""",D)
 page.locator('[name=mcq-subject]').select_option('english');page.get_by_text('3 questions · page 1',exact=True).wait_for();summary=page.get_by_role('complementary',name='Topic question totals');summary.get_by_text('3 questions',exact=True).wait_for();assert summary.bounding_box()['x']>page.locator('.mcq-filters').bounding_box()['x'];page.locator('[name=mcq-filter-topic]').select_option('Grammar');summary.get_by_text('2 questions',exact=True).wait_for();assert 'Teacher Alpha' in summary.inner_text();assert 'Teacher Beta' in summary.inner_text();page.get_by_text('2 questions · page 1',exact=True).wait_for();filters=page.locator('.mcq-contributor-filter');filters.locator('summary').click();filters.locator('[value="X:0"]').check();page.get_by_text('1 questions · page 1',exact=True).wait_for();assert page.locator('[data-question-id=QE001]').count()==1;assert page.locator('[data-question-id=QE002]').count()==0;assert summary.get_by_text('2 questions',exact=True).is_visible();assert '1 shown after filters' in summary.inner_text();filters.locator('[value="X:1"]').check();page.get_by_text('2 questions · page 1',exact=True).wait_for();filters.locator('[name=mcq-contributor-all]').check();page.locator('[name=mcq-search]').fill('BETA');page.get_by_text('1 questions · page 1',exact=True).wait_for();assert page.locator('[data-question-id=QE002]').count()==1;assert page.locator('[data-question-id=QE001]').count()==0;page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');assert summary.bounding_box()['y']>=page.locator('.mcq-filters').bounding_box()['y']+page.locator('.mcq-filters').bounding_box()['height'];b.close()
